import{_ as s,c as a,o as n,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"SSH Keys","description":"","frontmatter":{"title":"SSH Keys"},"headers":[],"relativePath":"general/ssh-keys.md","filePath":"general/ssh-keys.md","lastUpdated":null}'),i={name:"general/ssh-keys.md"};function r(o,e,l,p,c,d){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="ssh-keys" tabindex="-1">SSH Keys <a class="header-anchor" href="#ssh-keys" aria-label="Permalink to &quot;SSH Keys&quot;">​</a></h1><h2 id="ssh-keys-1" tabindex="-1">SSH Keys <a class="header-anchor" href="#ssh-keys-1" aria-label="Permalink to &quot;SSH Keys&quot;">​</a></h2><h3 id="what-they-are" tabindex="-1">What They Are <a class="header-anchor" href="#what-they-are" aria-label="Permalink to &quot;What They Are&quot;">​</a></h3><p>SSH keys are a pair of cryptographic keys used for secure access to systems over a network. They consist of a public key, which is shared, and a private key, which is kept secret. SSH keys provide a more secure and convenient way to authenticate than traditional passwords.</p><h3 id="difference-between-ssh-and-gpg-keys" tabindex="-1">Difference Between SSH and GPG Keys <a class="header-anchor" href="#difference-between-ssh-and-gpg-keys" aria-label="Permalink to &quot;Difference Between SSH and GPG Keys&quot;">​</a></h3><ul><li><p><strong>SSH Keys</strong>: Used primarily for secure authentication to servers and services. They provide access control and secure communication.</p></li><li><p><strong>GPG Keys</strong>: Used for encrypting, decrypting, and signing emails and files. GPG keys provide data integrity and authenticity.</p></li></ul><p><strong>Always remember NEVER share your PRIVATE keys</strong></p><h3 id="key-type-comparison" tabindex="-1">Key Type Comparison <a class="header-anchor" href="#key-type-comparison" aria-label="Permalink to &quot;Key Type Comparison&quot;">​</a></h3><p><strong>Recommendation</strong> -</p><ul><li><p><strong>Best for security and performance</strong>: <strong>ssh-ed25519</strong></p><ul><li><strong>Strengths</strong>: Very strong security, small key size, fast performance.</li><li><strong>Weaknesses</strong>: Newer, less universally supported (but rapidly growing).</li><li><strong>Use case</strong>: Best for strong security and performance where supported.</li></ul></li><li><p><strong>ssh-rsa</strong> (Most Compatible)</p><ul><li><strong>Strengths</strong>: Widely supported, highly compatible.</li><li><strong>Weaknesses</strong>: Requires larger keys for equivalent security, slower performance.</li><li><strong>Use case</strong>: Best for broad compatibility.</li></ul></li><li><p><strong>ecdsa-sha2-nistp256</strong>, <strong>ecdsa-sha2-nistp384</strong>, <strong>ecdsa-sha2-nistp521</strong></p><ul><li><strong>Strengths</strong>: Strong security with smaller key sizes, better performance.</li><li><strong>Weaknesses</strong>: Potentially weaker NIST curves, less compatibility.</li><li><strong>Use case</strong>: Good for strong security and performance where compatibility is less critical.</li></ul></li><li><p><strong>ssh-dss</strong> (Don’t Use)</p><ul><li><strong>Strengths</strong>: Early standard.</li><li><strong>Weaknesses</strong>: Limited to 1024-bit keys, weaker security, often deprecated.</li><li><strong>Use case</strong>: Not recommended.</li></ul></li></ul><h3 id="creating-your-keys" tabindex="-1">Creating Your Keys <a class="header-anchor" href="#creating-your-keys" aria-label="Permalink to &quot;Creating Your Keys&quot;">​</a></h3><h3 id="terminal" tabindex="-1">Terminal <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;Terminal&quot;">​</a></h3><p>To generate an SSH key using the terminal, use the following command:</p><p><strong>Most Secure Keys</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-keygen -t ssh-ed25519 -C &quot;your_email@example.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Advanced ED25519 Command</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-keygen -t ed25519 -C &quot;username@example.com&quot; -f ~/.ssh/username_id_ed25519 -N &quot;your_passphrase&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>Compatible and Secure</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-keygen -t rsa -b 4096 -C &quot;your_email@example.com&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Follow the prompts to save the key, typically in <code>~/.ssh/id_rsa</code>.</p><h3 id="gui" tabindex="-1">GUI <a class="header-anchor" href="#gui" aria-label="Permalink to &quot;GUI&quot;">​</a></h3><p>Tools like <a href="https://www.puttygen.com/" target="_blank" rel="noreferrer">PuTTYgen</a> for Windows or <a href="https://support.apple.com/guide/keychain-access/welcome/mac" target="_blank" rel="noreferrer">Keychain Access</a> for macOS can be used to generate SSH keys using a graphical interface.</p><h3 id="using-your-keys" tabindex="-1">Using Your Keys <a class="header-anchor" href="#using-your-keys" aria-label="Permalink to &quot;Using Your Keys&quot;">​</a></h3><h3 id="using-to-ssh" tabindex="-1">Using to SSH <a class="header-anchor" href="#using-to-ssh" aria-label="Permalink to &quot;Using to SSH&quot;">​</a></h3><p>To use your SSH key for connecting to a server, add your public key to the <code>~/.ssh/authorized_keys</code> file on the server:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-add ~/.ssh/username_id_ed25519</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>After this, you can log in to the server (remote) with <code>ssh username@host.tld</code>. If you are prompted for your PIN, it is the PIN you created when generating your SSH keys.</p><p>You may also SSH directly to a server without adding your SSH key to the server’s <code>~/.ssh/authorized_keys</code> file:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh -i ~/.ssh/username_id_ed25519 username@hostname</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="using-with-git" tabindex="-1">Using with Git <a class="header-anchor" href="#using-with-git" aria-label="Permalink to &quot;Using with Git&quot;">​</a></h3><h4 id="private-repos" tabindex="-1">Private Repos <a class="header-anchor" href="#private-repos" aria-label="Permalink to &quot;Private Repos&quot;">​</a></h4><p>To use your SSH key with private Git repositories, add the key to your SSH agent and configure the repository URL to use SSH:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-add ~/.ssh/username_id_ed25519</span></span>
<span class="line"><span>git remote set-url origin git@github.com:username/repo.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="using-to-sign-git-commits" tabindex="-1">Using to Sign Git Commits <a class="header-anchor" href="#using-to-sign-git-commits" aria-label="Permalink to &quot;Using to Sign Git Commits&quot;">​</a></h4><p>To sign Git commits with your SSH key, configure Git to use the key:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>git config --global user.signingkey &lt;your-key-id&gt;</span></span>
<span class="line"><span>git config --global commit.gpgSign true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="using-gpg-keys-for-ssh-authentication" tabindex="-1">Using GPG Keys for SSH Authentication <a class="header-anchor" href="#using-gpg-keys-for-ssh-authentication" aria-label="Permalink to &quot;Using GPG Keys for SSH Authentication&quot;">​</a></h3><h4 id="generating-a-gpg-key-pair" tabindex="-1">Generating a GPG Key Pair <a class="header-anchor" href="#generating-a-gpg-key-pair" aria-label="Permalink to &quot;Generating a GPG Key Pair&quot;">​</a></h4><p>If you don’t already have a GPG key pair, generate one:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>gpg --full-generate-key</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Follow the prompts to create your key pair.</p><h4 id="enabling-ssh-support-in-gpg" tabindex="-1">Enabling SSH Support in GPG <a class="header-anchor" href="#enabling-ssh-support-in-gpg" aria-label="Permalink to &quot;Enabling SSH Support in GPG&quot;">​</a></h4><p>Edit or create the <code>~/.gnupg/gpg-agent.conf</code> file to include the following line:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>enable-ssh-support</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="starting-the-gpg-agent" tabindex="-1">Starting the GPG Agent <a class="header-anchor" href="#starting-the-gpg-agent" aria-label="Permalink to &quot;Starting the GPG Agent&quot;">​</a></h4><p>Start or reload the GPG agent:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>gpg-connect-agent updatestartuptty /bye</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="extracting-the-ssh-public-key-from-your-gpg-key" tabindex="-1">Extracting the SSH Public Key from Your GPG Key <a class="header-anchor" href="#extracting-the-ssh-public-key-from-your-gpg-key" aria-label="Permalink to &quot;Extracting the SSH Public Key from Your GPG Key&quot;">​</a></h4><p>Use the following command to extract the SSH public key from your GPG key:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>ssh-add -L</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>If the key is not listed, you can add it manually:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>gpg --export-ssh-key &lt;your-gpg-key-id&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Replace <code>&amp;lt;your-gpg-key-id&amp;gt;</code> with your actual GPG key ID.</p><h4 id="adding-the-public-key-to-your-authorized-keys-on-the-remote-server" tabindex="-1">Adding the Public Key to Your <code>authorized_keys</code> on the Remote Server <a class="header-anchor" href="#adding-the-public-key-to-your-authorized-keys-on-the-remote-server" aria-label="Permalink to &quot;Adding the Public Key to Your \`authorized_keys\` on the Remote Server&quot;">​</a></h4><p>Copy the extracted public key and add it to the <code>~/.ssh/authorized_keys</code> file on the remote server.</p><h4 id="configuring-your-shell-to-use-the-gpg-agent-for-ssh" tabindex="-1">Configuring Your Shell to Use the GPG Agent for SSH <a class="header-anchor" href="#configuring-your-shell-to-use-the-gpg-agent-for-ssh" aria-label="Permalink to &quot;Configuring Your Shell to Use the GPG Agent for SSH&quot;">​</a></h4><p>Ensure your SSH client is configured to use the GPG agent by adding the following to your <code>~/.bashrc</code> or <code>~/.zshrc</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>export SSH_AUTH_SOCK=$(gpgconf --list-dirs agent-ssh-socket)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Reload your shell configuration:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>source ~/.bashrc  ## or source ~/.zshrc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>By following these steps, you can use your GPG key for SSH authentication, leveraging the benefits of GPG key management.</p><h3 id="securely-storing-your-keys" tabindex="-1">Securely Storing Your Keys <a class="header-anchor" href="#securely-storing-your-keys" aria-label="Permalink to &quot;Securely Storing Your Keys&quot;">​</a></h3><h3 id="ssh-agent" tabindex="-1">SSH Agent <a class="header-anchor" href="#ssh-agent" aria-label="Permalink to &quot;SSH Agent&quot;">​</a></h3><p>Use <code>ssh-agent</code> to manage your keys and avoid entering the passphrase multiple times:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>eval &quot;$(ssh-agent -s)&quot;</span></span>
<span class="line"><span>ssh-add ~/.ssh/username_id_ed25519</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="keypassxc" tabindex="-1">KeyPassXC <a class="header-anchor" href="#keypassxc" aria-label="Permalink to &quot;KeyPassXC&quot;">​</a></h3><p><a href="https://keepassxc.org/" target="_blank" rel="noreferrer">KeyPassXC</a> is a cross-platform password manager that can securely store your SSH keys.</p><p>When configuring your .ssh/config file you may want to pass the IdentityFile directive to a host to ensure that the ssh agent only uses a specific key to connect to a host. This directive requires you to provide the path to your key file. When we add an ssh key to the KeePassXC agent we are deleting the file from our filesystem in order to protect it which conflicts with this. The solution is to pass the .pub public key file for your host to the IdentityFile instead of the private key. you can generate a key as described in the above sections. Add that key to your keepassxc agent to protect it and then keep the public key in your .ssh/ directory. This will allow you to set your .ssh/config to use a key that is only available in the agent.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>Host git.example.com</span></span>
<span class="line"><span>  Hostname git.example.com</span></span>
<span class="line"><span>  Port 22</span></span>
<span class="line"><span>  User git</span></span>
<span class="line"><span>  PreferredAuthentications publickey</span></span>
<span class="line"><span>  IdentityFile ~/.ssh/mygitkey.pub</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><ul><li><p><a href="https://www.openssh.com/" target="_blank" rel="noreferrer">OpenSSH</a></p></li><li><p><a href="https://www.puttygen.com/" target="_blank" rel="noreferrer">PuTTYgen</a></p></li><li><p><a href="https://support.apple.com/guide/keychain-access/welcome/mac" target="_blank" rel="noreferrer">Keychain Access</a></p></li><li><p><a href="https://keepassxc.org/" target="_blank" rel="noreferrer">KeyPassXC</a></p></li></ul>`,71)])])}const g=s(i,[["render",r]]);export{u as __pageData,g as default};
